import type { TimestampedObject, TrackedValueOpts, TrimReason } from './types.js';
import { TrackerBase } from './tracker-base.js';

/**
 * A tracked value of type `V`.
 */
export abstract class ObjectTracker<V extends object, SeenResultType> extends TrackerBase<V, SeenResultType> {
  values: TimestampedObject<V>[];

  constructor(opts: TrackedValueOpts = {}) {
    super(opts);
    this.values = [];
  }

  onTrimmed(reason: TrimReason): void {
    // no-op
  }

  /**
   * Reduces size of value store to `limit`. 
   * Returns number of remaining items
   * @param limit
   */
  trimStore(limit: number): number {
    if (limit >= this.values.length) return this.values.length;
    // Index 0 will be the oldest
    this.values = this.values.slice(-limit);
    return this.values.length;
  }

  /**
   * Allows sub-classes to be notified when a reset happens
   * @ignore
   */
  onReset(): void {
    this.values = [];
  }

  /**
   * Tracks a value
   * @ignore
   */
  filterData(p: V[] | TimestampedObject<V>[]): TimestampedObject<V>[] {
    // Make sure values have a timestamp
    const ts = p.map((v) =>
      `at` in v
        ? v
        : {
          ...v,
          at: Date.now(),
        }
    );

    // eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    const last = ts.at(-1)!;

    if (this.storeIntermediate) this.values.push(...ts);
    else switch (this.values.length) {
      case 0: {
        // Add as initial value
        this.values.push(last);
        break;
      }
      case 1: {
        // Add last value
        this.values.push(last);
        break;
      }
      case 2: {
        // Replace last value
        this.values[ 1 ] = last;
        break;
      }
    }
    return ts;
  }

  /**
   * Last seen value. If no values have been added, it will return the initial value
   */
  get last(): TimestampedObject<V> {
    if (this.values.length === 1) return this.values[ 0 ];
    //eslint-disable-next-line @typescript-eslint/no-non-null-assertion
    return this.values.at(-1)!;
  }

  /**
   * Returns the oldest value in the buffer
   */
  get initial(): TimestampedObject<V> | undefined {
    return this.values.at(0);
  }

  /**
   * Returns number of recorded values (includes the initial value in the count)
   */
  get size(): number {
    return this.values.length;
  }

  /**
   * Returns the elapsed time, in milliseconds since the initial value
   */
  get elapsed(): number {
    if (this.values.length === 0) throw new Error(`No values seen yet`);
    return Date.now() - this.values[ 0 ].at;
  }

  /**
   * Returns the time, in milliseconds, covering the initial and last values.
   * Returns NaN if either of these is missing.
   */
  get timespan(): number {
    const oldest = this.initial;
    const newest = this.last;
    if (!oldest) return Number.NaN;
    if (!newest) return Number.NaN;
    return newest.at - oldest.at;
  }
}
